import fs from'node:fs';import assert from'node:assert/strict';import{Backend}from'../mcp/backend.mjs';
const wanted=process.argv.includes('--safari')?'ios-safari':'ios-chrome';const b=new Backend();let session;const proof={at:new Date().toISOString(),scope:`Actual local synthetic client /meet lobby on physical iPhone ${wanted}; untethered private HTTPS; no call joined or off-LAN claim`};
try{
 const initial=(await b.webPages()).pages.find(p=>p.browser===wanted&&p.visible&&p.ready);assert(initial);session=(await b.begin({surface:'web',page:initial.id})).sessionId;
 const nav=await b.webAction({sessionId:session,action:'evaluate',args:{expression:"void window.next.router.push('/meet');({requested:true})"}});assert(nav.ok);await b.webEnd(session);session=null;
 let target;const deadline=Date.now()+60000;while(Date.now()<deadline){target=(await b.webPages()).pages.find(p=>p.browser===wanted&&p.visible&&p.path==='/meet');if(target)break;await new Promise(r=>setTimeout(r,1000));}assert(target,'actual client lobby did not enroll');session=(await b.begin({surface:'web',page:target.id})).sessionId;
 const run=(action,args={})=>b.webAction({sessionId:session,action,args});let s=await run('snapshot');assert(s.ok);const fields=s.value.elements.filter(e=>e.tag==='input');proof.dom={nodes:s.value.elements.length,fields:fields.map(e=>({label:e.label,type:e.tag})),buttons:s.value.elements.filter(e=>e.tag==='button').map(e=>e.label)};
 const auth=await run('evaluate',{expression:`(async()=>{const entry=document.cookie.split(';').map(s=>s.trim()).find(s=>s.startsWith('session-token='));const token=entry?decodeURIComponent(entry.slice('session-token='.length)):'';const r=await fetch('/api/ios-web-graphql',{method:'POST',headers:{'Content-Type':'application/json',authorization:token?'Bearer '+token:''},body:JSON.stringify({query:'{me{user{client{id}coach{id}}}}'})});const v=await r.json();return {status:r.status,clientAuthenticated:!!v.data?.me?.user?.client?.id,errors:!!v.errors}})()`});assert(auth.ok&&auth.value.clientAuthenticated&&!auth.value.errors);
 s=await run('snapshot');const toggle=s.value.elements.find(e=>e.tag==='button'&&e.label==='Background options');assert(toggle);assert((await run('click',{snapshot:s.value.snapshot,target:toggle.id})).ok);s=await run('snapshot');assert(s.value.elements.some(e=>e.tag==='button'&&e.label==='Blur'));const close=s.value.elements.find(e=>e.tag==='button'&&e.label==='Close');assert(close);assert((await run('click',{snapshot:s.value.snapshot,target:close.id})).ok);s=await run('snapshot');assert(!s.value.elements.some(e=>e.tag==='button'&&e.label==='Blur'));
 const gate=await b.webVerify({sessionId:session,gate:'web-route',expectedPath:'/meet'});assert(gate.ok);const state=await run('state');assert(state.ok&&state.value.domains.meet);proof.meetReaderPresent=true;proof.gates={actualClientRoute:true,reactMenuReadback:true,menuRestored:true,clientAuthenticationReadback:true,routeReceipt:true,callJoined:false};assert((await run('evaluate',{expression:"void window.next.router.push('/dev/ios-agent');({requested:true})"})).ok);const end=await b.webEnd(session);assert(end.indicatorOff);session=null;proof.gates.glowOff=true;
 fs.writeFileSync(new URL('../docs/mobile-web-client-lobby-'+wanted+'-2026-10-10.json',import.meta.url),JSON.stringify(proof,null,2)+'\n');console.log(JSON.stringify(proof));
}finally{if(session)await b.webEnd(session);await b.close();}
